package tracelet.policy

import rego.v1

default matched := false
default reason := ""

command := c if {
	c := object.get(input.event, "command_text", "")
	is_string(c)
}

default command := ""

# Commands that change deployed infrastructure (IaC apply/destroy, CFN
# stack operations, Kubernetes/Helm rollouts, direct service mutations).
infra_change_re := `(?:terraform|tofu)\s+(?:apply|destroy)\b|\bcdk\s+(?:deploy|destroy)\b|\bsam\s+(?:deploy|delete|sync)\b|\b(?:serverless|sls)\s+(?:deploy|remove)\b|\bpulumi\s+(?:up|destroy)\b|\baws\s+cloudformation\s+(?:create-stack|update-stack|delete-stack|deploy|execute-change-set)\b|\bkubectl\s+(?:apply|delete|rollout|scale|patch)\b|\bhelm\s+(?:install|upgrade|uninstall|rollback)\b|\baws\s+(?:ecs\s+update-service|lambda\s+update-function-(?:code|configuration)|eks\s+update-[a-z-]+|rds\s+(?:modify|delete|reboot)-[a-z-]+|ec2\s+(?:terminate|run|stop)-instances|autoscaling\s+update-auto-scaling-group|elbv2\s+(?:modify|delete)-[a-z-]+|route53\s+change-resource-record-sets)\b|\bansible-playbook\b|\beb\s+deploy\b|\bcopilot\s+(?:deploy|svc\s+deploy)\b`

infra_change if {
	command != ""
	regex.match(infra_change_re, command)
}

now_ns := time.now_ns()

# EDIT ME: declared change-freeze windows (RFC 3339, UTC). Add one object per
# freeze. A window is inclusive of `start`, exclusive of `end`.
freeze_windows := [
	{"name": "Year-end change freeze", "start": "2026-12-18T00:00:00Z", "end": "2027-01-05T00:00:00Z"},
]

active_freeze contains w.name if {
	some w in freeze_windows
	start := time.parse_rfc3339_ns(w.start)
	end := time.parse_rfc3339_ns(w.end)
	now_ns >= start
	now_ns < end
}

matched if {
	infra_change
	count(active_freeze) > 0
}

reason := sprintf("Infrastructure change attempted during the declared change freeze %v — wait for the window to close, or get an explicit break-glass approval from the change manager", [sort(active_freeze)]) if {
	matched
}

package tracelet.policy

import rego.v1

default matched := false
default reason := ""

command := c if {
	c := object.get(input.event, "command_text", "")
	is_string(c)
}

default command := ""

# Commands that change deployed infrastructure (IaC apply/destroy, CFN
# stack operations, Kubernetes/Helm rollouts, direct service mutations).
infra_change_re := `(?:terraform|tofu)\s+(?:apply|destroy)\b|\bcdk\s+(?:deploy|destroy)\b|\bsam\s+(?:deploy|delete|sync)\b|\b(?:serverless|sls)\s+(?:deploy|remove)\b|\bpulumi\s+(?:up|destroy)\b|\baws\s+cloudformation\s+(?:create-stack|update-stack|delete-stack|deploy|execute-change-set)\b|\bkubectl\s+(?:apply|delete|rollout|scale|patch)\b|\bhelm\s+(?:install|upgrade|uninstall|rollback)\b|\baws\s+(?:ecs\s+update-service|lambda\s+update-function-(?:code|configuration)|eks\s+update-[a-z-]+|rds\s+(?:modify|delete|reboot)-[a-z-]+|ec2\s+(?:terminate|run|stop)-instances|autoscaling\s+update-auto-scaling-group|elbv2\s+(?:modify|delete)-[a-z-]+|route53\s+change-resource-record-sets)\b|\bansible-playbook\b|\beb\s+deploy\b|\bcopilot\s+(?:deploy|svc\s+deploy)\b`

infra_change if {
	command != ""
	regex.match(infra_change_re, command)
}

now_ns := time.now_ns()

# EDIT ME: business hours (24h clock, inclusive start, exclusive end) and the
# timezone they are judged in.
tz := "UTC"
business_start_hour := 8
business_end_hour := 18

# Only production-targeted changes are gated after hours; non-prod work at
# night is normal. "prod" is looked for in the command (profile, workspace,
# stack, namespace, stage or var value).
prod_targeted if {
	regex.match(`(?i)(?:--profile[=\s]+\S*prod|AWS_PROFILE=\S*prod|\bworkspace\s+select\s+\S*prod|--stack-name[=\s]+\S*prod|--stage[=\s]+prod|-n\s+\S*prod\b|--namespace[=\s]+\S*prod|--context[=\s]+\S*prod|\benv(?:ironment)?=prod|\.tfvars\b[^|;&]*prod|prod[^|;&]*\.tfvars\b)`, command)
}

clock := time.clock([now_ns, tz])
hour := clock[0]

outside_hours if { hour < business_start_hour }
outside_hours if { hour >= business_end_hour }

matched if {
	infra_change
	prod_targeted
	outside_hours
}

reason := sprintf("Production infrastructure change at %02d:%02d %s, outside business hours (%02d:00–%02d:00) — after-hours prod changes need an approver awake to catch them; request access or wait for the maintenance window", [hour, clock[1], tz, business_start_hour, business_end_hour]) if {
	matched
}

