now_ns := time.now_ns()

# EDIT ME: the timezone the weekend is judged in.
tz := "UTC"

weekday := time.weekday([now_ns, tz])

matched if {
	infra_change
	weekday in {"Saturday", "Sunday"}
}

reason := sprintf("Infrastructure change on a %s (%s) — weekend changes run without the normal on-call bench; state why it cannot wait for the next business day", [weekday, tz]) if {
	matched
}
